Lemma mul_round_exact : forall signHi resHi resLo,
  mul_round signHi resHi resLo 0 0 = mk128 (Z.lor resHi signHi) resLo.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00$signHi;R+0$resHi;R+0$resLo;R+0!2,C+0!2'<!2'=#2#3#1").
Qed.

