Theorem f128_mul_exact : forall sa Ea Ta sb Eb Tb M k,
  packed sa Ea Ta -> packed sb Eb Tb -> 1 <= Ea <= 32766 -> 1 <= Eb <= 32766 ->
  (k = 0 \/ k = 1) -> 2^112 <= M < 2^113 ->
  (2^112 + Ta) * (2^112 + Tb) = M * 2^(112 + k) ->
